150		if _, err := s.Grant(doc, pid, rcv.ID,
151			[]Scope{{EncounterID: eid, Category: Diagnosis}},
152			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour)); err != nil {
153			t.Fatal(err)
154		}
155		if res, err := s.Read(rcv, pid, eid, Diagnosis); err != nil || len(res.Records) != 0 {
156			t.Fatalf("before activation: res=%+v err=%v", res, err)
